package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceMetricsModeOptions;

class MetricsModeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property metrics mode of observed source ")
  void test_metrics_mode_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> MetricsModeVO.tryFrom("_PUSH_"));
    Assertions.assertEquals(ObservedSourceMetricsModeOptions.PUSH,
        MetricsModeVO.tryFrom("PUSH").getMetricsMode().orElse(null));
    Assertions.assertFalse(MetricsModeVO.nullValue().getMetricsMode().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(MetricsModeVO.tryFrom(null).getMetricsMode().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(ObservedSourceMetricsModeOptions.PUSH,
        MetricsModeVO.from(ObservedSourceMetricsModeOptions.PUSH).getMetricsMode().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> MetricsModeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedSourceMetricsModeOptions.PUSH + "]",
        MetricsModeVO.from(ObservedSourceMetricsModeOptions.PUSH).toString());
  }
}
